import java.util.Scanner;

public class Main {
    static final int MAX_N = 100;
    static final int MAX_X = 100;
    static final int MD = 1000000007;

    static long power(int a, int k) {
        long result = 1;
        long base = a;
        while (k > 0) {
            if ((k & 1) == 1) {
                result = (result * base) % MD;
            }
            base = (base * base) % MD;
            k >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int x = scanner.nextInt();
        String s = scanner.next();
        scanner.close();

        if (x == 0) {
            System.out.println((n == 1 && s.charAt(0) == '0') ? 1 : 0);
            return;
        }

        int[] ff = new int[MAX_X + 1];
        int[][][] ds = new int[MAX_X + 1][MAX_N][MAX_N + 1];
        int[][] dp = new int[MAX_X + 1][MAX_N];
        int[][] dq = new int[MAX_X + 1][MAX_N];
        int[] dr = new int[MAX_X + 1];

        ff[0] = ff[1] = 1;
        for (int i = 2; i <= x; i++) {
            ff[i] = (ff[i - 1] + ff[i - 2]) % (MD - 1);
        }
        for (int i = 0; i <= x; i++) {
            ff[i] = (int) power(2, ff[i]);
        }

        for (int l = 0; l < n; l++) {
            ds[0][l][l] = ds[1][l][l] = 1;
            ds[0][l][l + 1] = (s.charAt(l) == '0') ? 1 : 0;
            ds[1][l][l + 1] = (s.charAt(l) == '1') ? 1 : 0;
        }

        for (int i = 2; i <= x; i++) {
            for (int l = 0; l < n; l++) {
                for (int r = l; r < n; r++) {
                    long z = 0;
                    for (int m = l; m <= r; m++) {
                        z = (z + (long) ds[i - 1][l][m] * ds[i - 2][m][r]) % MD;
                    }
                    ds[i][l][r] = (int) z;
                }
            }
        }

        if (n > 1) {
            dp[0][n - 1] = ds[0][n - 1][n];
            dp[1][n - 1] = ds[1][n - 1][n];
            for (int i = 2; i <= x; i++) {
                for (int l = 1; l < n; l++) {
                    long z = (long) dp[i - 1][l] * ff[i - 2] % MD;
                    for (int m = l; m < n; m++) {
                        z = (z + (long) ds[i - 1][l][m] * dp[i - 2][m]) % MD;
                    }
                    dp[i][l] = (int) z;
                }
            }

            dq[0][1] = ds[0][0][1];
            dq[1][1] = ds[1][0][1];
            for (int i = 2; i <= x; i++) {
                for (int r = 1; r < n; r++) {
                    long z = (long) ff[i - 1] * dq[i - 2][r] % MD;
                    for (int m = r; m > 0; m--) {
                        z = (z + (long) dq[i - 1][m] * ds[i - 2][m][r]) % MD;
                    }
                    dq[i][r] = (int) z;
                }
            }
        }

        dr[0] = ds[0][0][n];
        dr[1] = ds[1][0][n];
        for (int i = 2; i <= x; i++) {
            long z = ((long) dr[i - 1] * ff[i - 2] + (long) ff[i - 1] * dr[i - 2]) % MD;
            for (int m = 1; m < n; m++) {
